import math
from itertools import permutations

def is_perfect_square(k):
    if k < 1:
        return False
    root = int(math.isqrt(k))
    return root * root == k

def check_permutation(n, p):
    """Checks if a given permutation p satisfies the cool integer condition."""
    current_sum = 0
    for i in range(n):
        current_sum += p[i]
        if is_perfect_square(current_sum):
            return False  # Found a square partial sum
    return True # All partial sums are non-squares

def solve_cool_integer(n):
    """Checks if there exists at least one cool permutation for size n."""
    # We iterate through all permutations and check the condition
    for p in permutations(range(1, n + 1)):
        if check_permutation(n, p):
            return True
    return False

results = {}
for n in range(1, 13):
    is_cool = solve_cool_integer(n)
    results[n] = "Yes" if is_cool else "No"

print("Results for n=1 to 12:")
for n, cool in results.items():
    print(f"n={n}: {cool}")

import math

def is_perfect_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

N_max = 20000
non_cool_candidates = []

for n in range(1, N_max + 1):
    T_n = n * (n + 1) // 2
    if is_perfect_square(T_n):
        non_cool_candidates.append(n)

print(f"List of n <= {N_max} such that T_n is a perfect square: {non_cool_candidates}")
